def detect_root(value: str) -> Path:
    root = Path(value).expanduser().resolve()
    required = [
        root / "artisan_backend" / "manage.py",
        root / "artisan-frontend" / "package.json",
    ]
    if not all(path.exists() for path in required):
        raise SystemExit(
            "Racine ARTISAN_CI invalide. Lance ce script depuis le dossier du dépôt "
            "ou passe --root C:/chemin/vers/ARTISAN_CI."
        )
    return root


def backup_file(root: Path, backup_root: Path, rel: str) -> None:
    source = root / rel
    if not source.exists():
        return
    destination = backup_root / rel
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, destination)


def replace_exact(root: Path, backup_root: Path, rel: str, old: str, new: str) -> str:
    path = root / rel
    if not path.exists():
        raise RuntimeError(f"Fichier introuvable: {rel}")

    content = path.read_text(encoding="utf-8")
    if new in content:
        return "déjà appliqué"
    count = content.count(old)
    if count != 1:
        raise RuntimeError(
            f"Le bloc attendu n'a pas été trouvé exactement une fois dans {rel} "
            f"(trouvé {count} fois). Le dépôt a probablement changé: aucune modification hasardeuse n'a été faite."
        )

    backup_file(root, backup_root, rel)
    path.write_text(content.replace(old, new, 1), encoding="utf-8", newline="\n")
    return "modifié"


def write_new(root: Path, backup_root: Path, rel: str, content: str) -> str:
    path = root / rel
    if path.exists():
        current = path.read_text(encoding="utf-8")
        if current == content:
            return "déjà présent"
        backup_file(root, backup_root, rel)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8", newline="\n")
    return "créé"


def main() -> None:
    parser = argparse.ArgumentParser(description="Applique ARTISAN_CI INT 2 sur le dépôt local.")
    parser.add_argument("--root", default=".", help="Racine du dépôt ARTISAN_CI.")
    args = parser.parse_args()

    root = detect_root(args.root)
    backup_root = root / ".int2-backup" / datetime.now().strftime("%Y%m%d-%H%M%S")
    changes = []

    for rel, old, new in REPLACEMENTS:
        result = replace_exact(root, backup_root, rel, old, new)
        changes.append((rel, result))

    for rel, content in NEW_FILES.items():
        result = write_new(root, backup_root, rel, content)
        changes.append((rel, result))

    print("\nINT 2 appliqué avec succès.\n")
    for rel, result in changes:
        print(f"- {result:14} {rel}")
    print(f"\nSauvegarde des fichiers remplacés: {backup_root}")
    print("\nCommandes de validation recommandées:")
    print("  cd artisan_backend")
    print("  python manage.py makemigrations --check")
    print("  python manage.py migrate")
    print("  python manage.py check")
    print("  python manage.py test accounts")
    print("  cd ../artisan-frontend")
    print("  npm run build")
    print("\nPuis teste: inscription FR/CI, /client/adresses, changement d'adresse par défaut et réservation chez le client.")


if __name__ == "__main__":
    main()
